public int Search(int[] nums, int target) {
    int lo = 0, hi = nums.Length - 1;          // if target exists, it is in [lo..hi]
    while (lo <= hi) {                         // the interval is not empty
        int mid = lo + (hi - lo) / 2;          // no overflow
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) lo = mid + 1;  // nums[0..mid] < target
        else hi = mid - 1;                     // nums[mid..] > target
    }
    return -1;                                 // lo > hi: no candidates
}

