// a = [1, 3, 3, 3, 8]
// LowerBound(a, 3) = 1 — the first a[i] >= 3
// UpperBound(a, 3) = 4 — the first a[i] > 3
// three occurs 4 - 1 = 3 times, the last one at index 3
int LowerBound(int[] a, int x) {
    int lo = 0, hi = a.Length;              // a[0..lo) < x <= a[hi..n)
    while (lo < hi) {                       // the band [lo, hi) is not empty
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1;       // mid is among the smaller ones
        else hi = mid;                      // mid is among the not-smaller ones
    }
    return lo;
}

